import assert from "node:assert/strict";
import { mkdtemp, mkdir, realpath, rename, rm, symlink, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { Writable } from "node:stream";
import { pipeline } from "node:stream/promises";
import test, { type TestContext } from "node:test";

import { LocalAssets, normalizeAssetDirectories } from "./local-assets.js";

async function fixture(t: TestContext) {
    const base = await mkdtemp(path.join(os.tmpdir(), "canvas-local-assets-"));
    t.after(() => rm(base, { recursive: true, force: true }));
    const root = path.join(base, "allowed");
    const outside = path.join(base, "outside");
    await mkdir(path.join(root, "nested"), { recursive: true });
    await mkdir(outside);
    await writeFile(path.join(root, "产品.PNG"), "image");
    await writeFile(path.join(root, "nested", "Clip.MP4"), "video");
    await writeFile(path.join(root, "sound.mp3"), "audio");
    await writeFile(path.join(root, "notes.txt"), "not media");
    await writeFile(path.join(outside, "secret.png"), "outside");
    const directories = await normalizeAssetDirectories([root]);
    return { base, root, outside, directories, store: new LocalAssets(directories) };
}

test("默认无目录授权，配置只接受真实的绝对目录", async (t) => {
    const { root } = await fixture(t);
    await assert.rejects(new LocalAssets().search({}), /授权/);
    await assert.rejects(normalizeAssetDirectories(["relative"]), /绝对路径/);
    await assert.rejects(normalizeAssetDirectories([path.join(root, "产品.PNG")]), /目录/);
    await assert.rejects(normalizeAssetDirectories("invalid"), /绝对路径/);
    assert.deepEqual(await normalizeAssetDirectories([root, root]), [await realpath(root)]);
    assert.deepEqual(await normalizeAssetDirectories([]), []);
});

test("仅返回授权目录内的媒体，文件名匹配不区分大小写且类型可筛选", async (t) => {
    const { store, root, directories } = await fixture(t);
    const all = await store.search({});
    assert.equal(all.total, 3);
    assert.deepEqual(all.assets.map((asset) => asset.kind).sort(), ["audio", "image", "video"]);
    assert.deepEqual(all.warnings, []);
    assert.equal(JSON.stringify(all).includes(root), false);
    assert.equal(JSON.stringify(all).includes("base64"), false);
    assert.equal((await store.search({ keyword: "clip", kind: "video" })).assets[0].relativePath, path.join("nested", "Clip.MP4"));
    assert.equal((await store.search({ keyword: "产品", kind: "image" })).assets[0].size, 5);
    assert.equal((await store.search({ keyword: "clip", kind: "image" })).total, 0);
    assert.equal((await store.search({ keyword: "secret" })).total, 0);
    store.setDirectories([...directories, await realpath(path.join(root, "nested"))]);
    assert.equal((await store.search({})).total, 3);
});

test("不跟随授权目录内通往外部或自身的目录联接", async (t) => {
    const { store, root, outside } = await fixture(t);
    await symlink(outside, path.join(root, "escape"), process.platform === "win32" ? "junction" : "dir");
    await symlink(root, path.join(root, "cycle"), process.platform === "win32" ? "junction" : "dir");
    assert.equal((await store.search({})).total, 3);
});

test("文件内容以二进制流读取，临时 ID 不暴露原始路径", async (t) => {
    const { store } = await fixture(t);
    const asset = (await store.search({ kind: "video" })).assets[0];
    assert.deepEqual(Object.keys(asset).sort(), ["assetId", "directoryIndex", "fileName", "kind", "relativePath", "size"]);
    const file = await store.open(asset.assetId);
    const chunks: Buffer[] = [];
    try {
        assert.equal(file.contentType, "video/mp4");
        await pipeline(file.handle.createReadStream({ autoClose: false }), new Writable({ write(chunk, _encoding, callback) { chunks.push(chunk); callback(); } }));
        assert.equal(Buffer.concat(chunks).toString(), "video");
    } finally { await file.handle.close(); }
});

test("撤销授权、Agent 重启和文件变化均使旧 ID 失效", async (t) => {
    const { store, root, directories } = await fixture(t);
    const asset = (await store.search({ kind: "image" })).assets[0];
    await assert.rejects(new LocalAssets(directories).resolve(asset.assetId), /失效/);
    await writeFile(path.join(root, asset.fileName), "changed");
    await assert.rejects(store.open(asset.assetId), /已变化/);
    const refreshed = (await store.search({ kind: "image" })).assets[0];
    await rename(path.join(root, refreshed.fileName), path.join(root, "old.png"));
    await writeFile(path.join(root, refreshed.fileName), "changed");
    await assert.rejects(store.resolve(refreshed.assetId), /已变化/);
    store.setDirectories([]);
    await assert.rejects(store.open(refreshed.assetId), /失效/);
    await assert.rejects(store.resolve("../../secret.png"), /失效/);
});

test("搜索后目录被替换为外部联接时禁止读取旧素材", async (t) => {
    const { store, root, outside } = await fixture(t);
    const asset = (await store.search({ kind: "image" })).assets[0];
    await writeFile(path.join(outside, asset.fileName), "image");
    await rename(root, `${root}-old`);
    await symlink(outside, root, process.platform === "win32" ? "junction" : "dir");
    await assert.rejects(store.open(asset.assetId), /路径已变化/);
    await assert.rejects(store.search({}), /目录已变化/);
});

import crypto from "node:crypto";
import { open, readdir, realpath, stat } from "node:fs/promises";
import path from "node:path";

export type LocalAssetKind = "image" | "video" | "audio";
export type LocalAsset = { assetId: string; fileName: string; relativePath: string; directoryIndex: number; kind: LocalAssetKind; size: number };
type AssetRecord = { asset: LocalAsset; root: string; filePath: string; mtimeMs: number; ino: number; dev: number };

const mediaTypes: Record<string, [LocalAssetKind, string]> = {
    ".png": ["image", "image/png"], ".jpg": ["image", "image/jpeg"], ".jpeg": ["image", "image/jpeg"], ".webp": ["image", "image/webp"], ".gif": ["image", "image/gif"], ".avif": ["image", "image/avif"], ".svg": ["image", "image/svg+xml"], ".bmp": ["image", "image/bmp"],
    ".mp4": ["video", "video/mp4"], ".webm": ["video", "video/webm"], ".mov": ["video", "video/quicktime"], ".m4v": ["video", "video/mp4"], ".ogv": ["video", "video/ogg"],
    ".mp3": ["audio", "audio/mpeg"], ".wav": ["audio", "audio/wav"], ".ogg": ["audio", "audio/ogg"], ".m4a": ["audio", "audio/mp4"], ".aac": ["audio", "audio/aac"], ".flac": ["audio", "audio/flac"], ".opus": ["audio", "audio/ogg"],
};

/** 设置界面只接受用户明确填写的、已存在的绝对目录。 */
export async function normalizeAssetDirectories(value: unknown) {
    if (!Array.isArray(value) || value.some((item) => typeof item !== "string" || !path.isAbsolute(item.trim()))) throw new Error("素材目录必须是绝对路径列表");
    const directories: string[] = [];
    for (const item of value as string[]) {
        const directory = await realpath(item.trim());
        if (!(await stat(directory)).isDirectory()) throw new Error("素材路径必须是目录");
        if (!directories.includes(directory)) directories.push(directory);
    }
    return directories;
}

function isInside(root: string, filePath: string) {
    const relative = path.relative(root, filePath);
    return relative !== ".." && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative);
}

/** 临时 ID 只保存在本次 Agent 进程的会话中，不接受外部文件路径。 */
export class LocalAssets {
    private records = new Map<string, AssetRecord>();
    private directories: string[] = [];
    private revision = 0;

    constructor(directories: string[] = []) {
        this.setDirectories(directories);
    }

    setDirectories(directories: string[]) {
        this.directories = [...directories];
        this.revision++;
        this.records.clear();
    }

    async search(input: { keyword?: string; kind?: "all" | LocalAssetKind }) {
        if (!this.directories.length) throw new Error("请先在 Canvas Agent 设置中授权本地素材目录");
        const directories = [...this.directories];
        const revision = this.revision;
        const assets: LocalAsset[] = [];
        const warnings: string[] = [];
        const seen = new Set<string>();
        const keyword = (input.keyword || "").toLocaleLowerCase();
        for (const [directoryIndex, root] of directories.entries()) {
            if (await realpath(root) !== root) throw new Error("素材目录已变化，请重新授权");
            const walk = async (directory: string): Promise<void> => {
                for (const entry of await readdir(directory, { withFileTypes: true })) {
                    // 不跟随符号链接或目录联接，避免遍历到授权范围以外。
                    if (entry.isSymbolicLink()) continue;
                    const filePath = path.join(directory, entry.name);
                    try {
                        const resolved = await realpath(filePath);
                        if (!isInside(root, resolved)) continue;
                        if (entry.isDirectory()) { await walk(resolved); continue; }
                        const media = mediaTypes[path.extname(entry.name).toLowerCase()];
                        if (!entry.isFile() || !media || (input.kind && input.kind !== "all" && input.kind !== media[0]) || !entry.name.toLocaleLowerCase().includes(keyword) || seen.has(resolved)) continue;
                        const file = await stat(resolved);
                        if (!file.isFile()) continue;
                        seen.add(resolved);
                        if (revision !== this.revision) throw new Error("素材授权已变化，请重新搜索");
                        const asset: LocalAsset = { assetId: crypto.randomUUID(), fileName: entry.name, relativePath: path.relative(root, resolved), directoryIndex, kind: media[0], size: file.size };
                        this.records.set(asset.assetId, { asset, root, filePath: resolved, mtimeMs: file.mtimeMs, ino: file.ino, dev: file.dev });
                        assets.push(asset);
                    } catch (error) {
                        warnings.push(`目录 ${directoryIndex + 1} / ${path.relative(root, filePath)}：${(error as NodeJS.ErrnoException).code || "读取失败"}`);
                    }
                }
            };
            await walk(root);
        }
        if (revision !== this.revision) throw new Error("素材授权已变化，请重新搜索");
        return { assets, total: assets.length, warnings };
    }

    /** 导入和传输前重新检查真实路径、当前授权及文件是否仍与搜索结果一致。 */
    async resolve(assetId: string) {
        const record = this.records.get(assetId);
        if (!record || !this.directories.includes(record.root)) throw new Error("本地素材 ID 已失效，请重新搜索");
        const resolved = await realpath(record.filePath);
        if (resolved !== record.filePath || !isInside(record.root, resolved) || await realpath(record.root) !== record.root) throw new Error("素材路径已变化，请重新搜索");
        const file = await stat(resolved);
        this.checkFile(record, file);
        if (this.records.get(assetId) !== record) throw new Error("本地素材 ID 已失效，请重新搜索");
        return record;
    }

    /** 用二进制流传输文件，文件内容不会进入 MCP JSON。 */
    async open(assetId: string) {
        const record = await this.resolve(assetId);
        const handle = await open(record.filePath, "r");
        try {
            this.checkFile(record, await handle.stat());
            if (!this.records.has(assetId)) throw new Error("本地素材 ID 已失效，请重新搜索");
            return { handle, contentType: mediaTypes[path.extname(record.filePath).toLowerCase()][1], size: record.asset.size };
        } catch (error) {
            await handle.close();
            throw error;
        }
    }

    private checkFile(record: AssetRecord, file: Awaited<ReturnType<typeof stat>>) {
        if (!file.isFile() || file.size !== record.asset.size || file.mtimeMs !== record.mtimeMs || file.ino !== record.ino || file.dev !== record.dev) throw new Error("素材文件已变化，请重新搜索");
    }
}

