    return nodes.filter((node) => node.metadata?.groupId === groupId && isResourceNode(node));
}

function labelResourceNodes(nodes: CanvasNodeData[], active: boolean) {
    const counts: Record<CanvasResourceKind, number> = { image: 0, video: 0, audio: 0, text: 0 };
    return nodes.flatMap((node): CanvasResourceReference[] => {
        const kind = resourceKind(node);
        if (!kind) return [];
        const resource = getNodeDefinition(node.type)?.resource?.(node);
        const index = counts[kind]++;
        const label = labelForKind(kind, index);
        return [
            {
                id: node.id,
                nodeId: node.id,
                kind,
                label,
                title: node.title || label,
                previewUrl: node.metadata?.content || resource?.url,
                text: resourceText(node),
                active,
            },
        ];
    });
}

function labelForKind(kind: CanvasResourceKind, index: number) {
    if (kind === "image") return imageReferenceLabel(index);
    if (kind === "video") return i18n.t("canvas.configNode.videoReferences") + ` ${index + 1}`;
    if (kind === "audio") return i18n.t("canvas.configNode.audioReferences") + ` ${index + 1}`;
    return i18n.t("canvas.composer.resources.text", { index: index + 1 });
}

function isResourceNode(node: CanvasNodeData) {
    return Boolean(resourceKind(node));
}

function resourceText(node: CanvasNodeData): string | undefined {
    if (node.type === CanvasNodeType.Text) return node.metadata?.content || node.metadata?.prompt;
    const resource = getNodeDefinition(node.type)?.resource?.(node);
    return resource?.kind === "text" ? resource.text : undefined;
}

function resourceKind(node: CanvasNodeData): CanvasResourceKind | null {
    if (node.type === CanvasNodeType.Image && node.metadata?.content) return "image";
    if (node.type === CanvasNodeType.Video && node.metadata?.content) return "video";
    if (node.type === CanvasNodeType.Audio && node.metadata?.content) return "audio";
    if (node.type === CanvasNodeType.Text && (node.metadata?.content || node.metadata?.prompt)) return "text";
    // Plugin nodes declare their input eligibility through definition.resource.
    return getNodeDefinition(node.type)?.resource?.(node)?.kind || null;
}

export function getEffectiveVideoInputNodes(nodeId: string, nodes: CanvasNodeData[], connections: CanvasConnection[]): CanvasNodeData[] {
    const rawInputs = getGenerationResourceNodes(nodeId, nodes, connections);
    const result: CanvasNodeData[] = [];
    const seen = new Set<string>();
    for (const input of rawInputs) {
        if (input.type === CanvasNodeType.Group) {
            for (const member of getGroupResourceNodes(input.id, nodes)) {
                if (isResourceNode(member) && !seen.has(member.id)) {
                    seen.add(member.id);
                    result.push(member);
                }
            }
        } else if (isResourceNode(input) && !seen.has(input.id)) {
            seen.add(input.id);
            result.push(input);
        }
    }
    return result;
}

export function buildVideoInputList(
    sourceNode: CanvasNodeData,
    nodes: CanvasNodeData[],
    connections: CanvasConnection[],
    subjects: CanvasSubject[] = [],
    prompt = "",
    modelOverride?: string,
): VideoInputItem[] {
    const effectiveNodes = getEffectiveVideoInputNodes(sourceNode.id, nodes, connections);
    const items: VideoInputItem[] = [];
    const counts = { image: 0, video: 0, audio: 0, text: 0 };
    const effectiveModel = (modelOverride || sourceNode.metadata?.model || "").trim();
    const isH3 = /h3/i.test(effectiveModel);

    for (const node of effectiveNodes) {
        const kind = resourceKind(node);
        if (!kind) continue;
        const number = ++counts[kind];
        let h3Tag: string | undefined;
        let previewUrl: string | undefined;
        let text: string | undefined;
        let disabled: boolean | undefined;
        let disabledReason: string | undefined;

        if (kind === "image") {
            h3Tag = `<Picture ${number}>`;
            const resource = getNodeDefinition(node.type)?.resource?.(node);
            previewUrl = node.metadata?.content || resource?.url;
        } else if (kind === "video") {
            h3Tag = `<Video ${number}>`;
            const resource = getNodeDefinition(node.type)?.resource?.(node);
            previewUrl = node.metadata?.content || resource?.url;
            if (isH3) {
                disabled = true;
                disabledReason = i18n.t("canvas.videoInput.issues.unsupportedVideoMedia") || "当前工作流不支持视频输入，无可用字段";
            }
        } else if (kind === "audio") {
            h3Tag = `<Audio ${number}>`;
        } else if (kind === "text") {
            text = resourceText(node);
        }

        const isRef = Boolean(
            prompt.includes(`@[node:${node.id}]`) ||
            (h3Tag && prompt.includes(h3Tag)) ||
            (kind === "image" && new RegExp(`\\b(?:picture|image)[_ ]${number}\\b`, "i").test(prompt)) ||
            (kind === "video" && new RegExp(`\\bvideo[_ ]${number}\\b`, "i").test(prompt)) ||
            (kind === "audio" && new RegExp(`\\baudio[_ ]${number}\\b`, "i").test(prompt))
        );

        items.push({
            kind,
            stableId: `node:${node.id}`,
            nodeId: node.id,
            name: node.title || (kind === "text" ? `文本 ${number}` : `${kind} ${number}`),
            number,
            h3Tag,
            referenced: isRef,
            previewUrl,
            text,
            disabled,
            disabledReason,
        });
    }

    const effectiveNodeIds = new Set(effectiveNodes.map((n) => n.id));
    const activeBindings = (sourceNode.metadata?.videoBindings || []).filter(
        (binding) => binding.subjectId && effectiveNodeIds.has(binding.nodeId)
    );
    const seenSubjectIds = new Set<string>();
    let subjectCount = 0;

    for (const binding of activeBindings) {
        if (!binding.subjectId || seenSubjectIds.has(binding.subjectId)) continue;
        const subject = subjects.find((s) => s.subjectId === binding.subjectId);
        if (!subject) continue;
        seenSubjectIds.add(binding.subjectId);
        subjectCount++;
        const h3Tag = `<Subject ${subjectCount}>`;
        const isRef = Boolean(
            prompt.includes(`@[subject:${subject.subjectId}]`) ||
            prompt.includes(h3Tag) ||
            new RegExp(`\\bsubject[_ ]${subjectCount}\\b`, "i").test(prompt)
        );
        const boundNodes = effectiveNodes.filter((n) =>
            activeBindings.some((b) => b.subjectId === subject.subjectId && b.nodeId === n.id)
        );
        const boundNode = boundNodes[0];
        const boundPreview = boundNode?.metadata?.content || getNodeDefinition(boundNode?.type || "")?.resource?.(boundNode!)?.url;

        items.push({
            kind: "subject",
            stableId: `subject:${subject.subjectId}`,
            nodeId: boundNode?.id || binding.nodeId,
            name: subject.name,
            number: subjectCount,
            h3Tag,
            referenced: isRef,
            previewUrl: boundPreview,
            text: subject.description,
        });
    }

    return items;
}

import { FileText, Image as ImageIcon, Music2, Plus, Puzzle, Video, X, ChevronLeft, ChevronRight } from "lucide-react";
import { Popover } from "antd";
import { useSyncExternalStore, useState } from "react";
import { useTranslation } from "react-i18next";

import { canvasThemes } from "@/lib/canvas-theme";
import { getNodeDefinition } from "@/lib/canvas/node-registry";
import { getImagePreviewRevision, previewUrlFor, subscribeImagePreviews } from "@/services/image-storage";
import { useThemeStore } from "@/stores/use-theme-store";
import { CanvasNodeType, type CanvasNodeData } from "@/types/canvas";
import type { CanvasResourceReference } from "@/lib/canvas/canvas-resource-references";

export function CanvasNodeReferenceBar({ nodeId, planReferences, onDisconnect, onStartSelection, onOrderChange }: { nodeId: string; planReferences: CanvasResourceReference[]; onDisconnect?: (fromNodeId: string, toNodeId: string) => void; onStartSelection?: (nodeId: string) => void; onOrderChange?: (order: string[]) => void; }) {
    const { t } = useTranslation();
    const theme = canvasThemes[useThemeStore((state) => state.theme)];

    const [draggedIndex, setDraggedIndex] = useState<number | null>(null);

    const moveListItem = (index: number, offset: number) => {
        const nextOrder = planReferences.map(r => r.nodeId);
        const item = nextOrder.splice(index, 1)[0];
        nextOrder.splice(index + offset, 0, item);
        onOrderChange?.(nextOrder);
    };

    const handleDragStart = (index: number) => setDraggedIndex(index);
    const handleDragOver = (e: React.DragEvent, index: number) => {
        e.preventDefault();
    };
    const handleDrop = (index: number) => {
        if (draggedIndex !== null && draggedIndex !== index) {
            moveListItem(draggedIndex, index - draggedIndex);
        }
        setDraggedIndex(null);
    };

    return (
        <div className="mb-2">
            <div className="mb-1.5 text-[11px] font-medium" style={{ color: theme.node.muted }}>{t("canvas.references.title")}</div>
            <div className="thin-scrollbar flex min-h-12 gap-2 overflow-x-auto pb-1">
                {planReferences.map((ref, index) => <ReferenceItem key={ref.nodeId} reference={ref} onDragStart={() => handleDragStart(index)} onDragOver={(e) => handleDragOver(e, index)} onDrop={() => handleDrop(index)} isDragging={draggedIndex === index} onRemove={() => onDisconnect?.(ref.sourceNodeId || ref.nodeId, nodeId)} index={index} total={planReferences.length} onMove={offset => moveListItem(index, offset)} />)}
                <button type="button" className="grid size-12 shrink-0 place-items-center rounded-xl border bg-transparent transition hover:opacity-70" style={{ borderColor: theme.toolbar.border, color: theme.node.muted }} title={t("canvas.references.select")} onClick={() => onStartSelection?.(nodeId)}>
                    <Plus className="size-4" />
                </button>
            </div>
        </div>
    );
}

function ReferenceItem({ reference, onRemove, index, total, onMove, onDragStart, onDragOver, onDrop, isDragging }: { reference: CanvasResourceReference; onRemove: () => void; index: number; total: number; onMove: (offset: number) => void; onDragStart?: () => void; onDragOver?: (e: React.DragEvent) => void; onDrop?: () => void; isDragging?: boolean; }) {
    const { t } = useTranslation();
    const theme = canvasThemes[useThemeStore((state) => state.theme)];
    useSyncExternalStore(subscribeImagePreviews, getImagePreviewRevision, getImagePreviewRevision);

    const Icon = reference.kind === "image" ? ImageIcon : reference.kind === "video" ? Video : reference.kind === "audio" ? Music2 : reference.kind === "text" ? FileText : Puzzle;
    const thumbnail = previewUrlFor(reference.storageKey) || reference.previewUrl;

    return (
        <Popover placement="topLeft" mouseEnterDelay={0.15} content={<ReferencePreview reference={reference} />}>
            <div draggable onDragStart={onDragStart} onDragOver={onDragOver} onDrop={onDrop} className="group relative flex h-12 w-[84px] shrink-0 items-center overflow-hidden rounded-xl border cursor-grab active:cursor-grabbing" style={{ background: theme.toolbar.activeBg, borderColor: theme.toolbar.border, opacity: isDragging ? 0.3 : (reference.active ? 1 : 0.5) }}>
                <span className="grid size-12 shrink-0 place-items-center bg-black/10">
                    {(reference.kind === "image") && thumbnail ? <img src={thumbnail} alt="" className="size-full object-cover" /> : (reference.kind === "video") && reference.previewUrl ? <video src={reference.previewUrl} className="size-full object-cover" muted /> : <Icon className="size-4 opacity-65" />}
                </span>
                <span className="flex-1 truncate px-1 text-center text-[10px] font-medium leading-none" style={{ color: theme.node.text }} title={reference.label}>
                    {reference.label}
                </span>

                <div className="absolute inset-x-0 bottom-0 top-0 flex items-center justify-between bg-black/50 opacity-0 transition-opacity group-hover:opacity-100">
                    <button type="button" aria-label={t("canvas.references.moveLeft")} title={t("canvas.references.moveLeft")} disabled={index === 0} onClick={(e) => { e.stopPropagation(); onMove(-1); }} className="flex h-full w-4 items-center justify-center text-white hover:bg-white/20 disabled:opacity-30"><ChevronLeft className="size-3" /></button>
                    <button type="button" aria-label={t("canvas.references.moveRight")} title={t("canvas.references.moveRight")} disabled={index === total - 1} onClick={(e) => { e.stopPropagation(); onMove(1); }} className="flex h-full w-4 items-center justify-center text-white hover:bg-white/20 disabled:opacity-30"><ChevronRight className="size-3" /></button>
                </div>

                <button type="button" className="absolute right-0 top-0 grid size-5 -translate-y-1/3 translate-x-1/3 place-items-center rounded-full border opacity-0 shadow-sm transition-opacity group-hover:opacity-100 focus-visible:opacity-100" style={{ background: theme.toolbar.panel, borderColor: theme.toolbar.border, color: theme.node.text }} aria-label={reference.sourceNodeId ? t("canvas.references.disconnectGroup") : t("canvas.references.disconnect")} title={reference.sourceNodeId ? t("canvas.references.disconnectGroup") : t("canvas.references.disconnect")} onMouseDown={(event) => event.stopPropagation()} onClick={(event) => { event.stopPropagation(); onRemove(); }}><X className="size-3" /></button>
            </div>
        </Popover>
    );
}

function ReferencePreview({ reference }: { reference: CanvasResourceReference; }) {
    const { t } = useTranslation();
    if ((reference.kind === "image") && reference.previewUrl) return <img src={reference.previewUrl} alt={reference.title} className="max-h-52 w-72 rounded-lg object-contain" />;
    if ((reference.kind === "video") && reference.previewUrl) return <video src={reference.previewUrl} className="max-h-52 w-72 rounded-lg" muted controls />;
    if ((reference.kind === "audio") && reference.previewUrl) return <audio src={reference.previewUrl} className="w-72" controls />;
    return <div className="max-h-52 w-72 overflow-auto whitespace-pre-wrap text-sm">{reference.text || reference.title || t("canvas.references.empty")}</div>;
}

import { FileText, Image as ImageIcon, Music2, Plus, Puzzle, Users, Video, X } from "lucide-react";
import { Popover, theme as antdTheme } from "antd";
import type { GlobalToken } from "antd/es/theme/interface";
import { useSyncExternalStore, useState } from "react";
import { useTranslation } from "react-i18next";

import { canvasThemes } from "@/lib/canvas-theme";
import { getNodeDefinition } from "@/lib/canvas/node-registry";
import { getGroupResourceNodes } from "@/lib/canvas/canvas-resource-references";
import { getImagePreviewRevision, previewUrlFor, subscribeImagePreviews } from "@/services/image-storage";
import { useThemeStore } from "@/stores/use-theme-store";
import { CanvasNodeType, type CanvasNodeData, type CanvasSubject, type CanvasVideoBinding, type VideoInputItem } from "@/types/canvas";

export function CanvasNodeReferenceBar({
    nodeId,
    nodes,
    connectedNodes,
    videoBindings = [],
    subjects = [],
    inputList = [],
    onDisconnect,
    onStartSelection,
    onInsertReference,
}: {
    nodeId: string;
    nodes: CanvasNodeData[];
    connectedNodes: CanvasNodeData[];
    videoBindings?: CanvasVideoBinding[];
    subjects?: CanvasSubject[];
    inputList?: VideoInputItem[];
    onDisconnect?: (fromNodeId: string, toNodeId: string) => void;
    onStartSelection?: (nodeId: string) => void;
    onInsertReference?: (item: VideoInputItem) => void;
}) {
    const { t } = useTranslation();
    const theme = canvasThemes[useThemeStore((state) => state.theme)];
    const { token } = antdTheme.useToken();
    const [insertMenuOpen, setInsertMenuOpen] = useState(false);

    const references = connectedNodes.flatMap((sourceNode) =>
        (sourceNode.type === CanvasNodeType.Group ? getGroupResourceNodes(sourceNode.id, nodes) : [sourceNode]).map((node) => ({
            node,
            sourceNodeId: sourceNode.id,
            bindingLabels: videoBindings
                .filter((binding) => binding.nodeId === node.id)
                .map((binding) => {
                    const subject = subjects.find((item) => item.subjectId === binding.subjectId);
                    return `${subject ? `${subject.name} · ` : ""}${t(`canvas.videoInput.usages.${binding.usage}`)}`;
                }),
        })),
    );

    const handleSelectInputItem = (item: VideoInputItem) => {
        if (item.disabled) return;
        setInsertMenuOpen(false);
        onInsertReference?.(item);
    };

    const handleConnectOnCanvas = () => {
        setInsertMenuOpen(false);
        onStartSelection?.(nodeId);
    };

    const insertMenuContent = (
        <div className="w-64 space-y-2 p-1" style={{ color: theme.node.text }}>
            <div className="flex items-center justify-between border-b pb-1 text-xs font-medium" style={{ borderColor: theme.toolbar.border }}>
                <span>{t("canvas.videoInput.insertReference")}</span>
                {onStartSelection ? (
                    <button
                        type="button"
                        className="text-[11px] underline opacity-70 hover:opacity-100"
                        onClick={handleConnectOnCanvas}
                    >
                        {t("canvas.references.select")}
                    </button>
                ) : null}
            </div>
            {inputList.length ? (
                <div className="thin-scrollbar max-h-56 space-y-1 overflow-y-auto">
                    {inputList.map((item) => (
                        <button
                            key={item.stableId}
                            type="button"
                            disabled={item.disabled}
                            className={`flex w-full items-center gap-2 rounded-lg p-1.5 text-left text-xs transition ${
                                item.disabled ? "cursor-not-allowed opacity-50" : "hover:bg-black/5 dark:hover:bg-white/10"
                            }`}
                            onClick={() => handleSelectInputItem(item)}
                            title={item.disabled ? item.disabledReason : undefined}
                        >
                            {item.kind === "image" && item.previewUrl ? (
                                <img src={item.previewUrl} alt="" className="size-7 rounded object-cover" />
                            ) : item.kind === "video" && item.previewUrl ? (
                                <video src={item.previewUrl} className="size-7 rounded bg-black object-cover" muted />
                            ) : item.kind === "subject" && item.previewUrl ? (
                                <div className="relative size-7 overflow-hidden rounded">
                                    <img src={item.previewUrl} alt="" className="size-full object-cover" />
                                    <span className="absolute bottom-0 right-0 rounded-tl bg-black/60 p-0.5 text-white">
                                        <Users className="size-2" />
                                    </span>
                                </div>
                            ) : (
                                <span className="grid size-7 place-items-center rounded bg-transparent">
                                    {item.kind === "audio" ? (
                                        <Music2 className="size-3.5 opacity-65" />
                                    ) : item.kind === "video" ? (
                                        <Video className="size-3.5 opacity-65" />
                                    ) : item.kind === "text" ? (
                                        <FileText className="size-3.5 opacity-65" />
                                    ) : item.kind === "subject" ? (
                                        <Users className="size-3.5 opacity-65" />
                                    ) : (
                                        <ImageIcon className="size-3.5 opacity-65" />
                                    )}
                                </span>
                            )}
                            <div className="min-w-0 flex-1">
                                <div className="truncate font-medium">{item.h3Tag ? `${item.h3Tag} ${item.name}` : item.name}</div>
                                <div className="truncate text-[10px] opacity-60">{item.text || item.kind}</div>
                            </div>
                            {item.disabled ? (
                                <span
                                    className="shrink-0 rounded px-1 py-0.5 text-[9px] font-medium"
                                    style={{ color: token.colorError, background: token.colorErrorBg }}
                                >
                                    {t("canvas.videoInput.issues.unsupportedVideoMedia") || "不支持"}
                                </span>
                            ) : null}
                        </button>
                    ))}
                </div>
            ) : (
                <div className="py-4 text-center text-xs opacity-60">
                    <div>{t("canvas.references.emptyConnected") || "请先在画布上连接素材"}</div>
                    {onStartSelection ? (
                        <button
                            type="button"
                            className="mt-2 rounded border px-2.5 py-1 text-xs"
                            style={{ borderColor: theme.toolbar.border }}
                            onClick={handleConnectOnCanvas}
                        >
                            {t("canvas.references.select")}
                        </button>
                    ) : null}
                </div>
            )}
        </div>
    );

    const hasInputListCards = inputList.length > 0;

    return (
        <div className="mb-2">
            <div className="mb-1.5 text-[11px] font-medium" style={{ color: theme.node.muted }}>
                {t("canvas.references.title")}
            </div>
            <div className="thin-scrollbar flex min-h-12 gap-2 overflow-x-auto pb-1">
                {hasInputListCards
                    ? inputList.map((item) => (
                          <ReferenceInputCard
                              key={item.stableId}
                              item={item}
                              token={token}
                              theme={theme}
                              onRemove={item.nodeId ? () => onDisconnect?.(item.nodeId!, nodeId) : undefined}
                          />
                      ))
                    : references.map(({ node, sourceNodeId, bindingLabels }) => (
                          <ReferenceItem
                              key={`${sourceNodeId}:${node.id}`}
                              node={node}
                              bindingLabels={bindingLabels}
                              onRemove={() => onDisconnect?.(sourceNodeId, nodeId)}
                          />
                      ))}

                {onInsertReference ? (
                    <Popover
                        open={insertMenuOpen}
                        onOpenChange={setInsertMenuOpen}
                        content={insertMenuContent}
                        trigger="click"
                        placement="bottomLeft"
                    >
                        <button
                            type="button"
                            className="grid size-12 shrink-0 place-items-center rounded-xl border bg-transparent transition hover:opacity-70"
                            style={{ borderColor: theme.toolbar.border, color: theme.node.muted }}
                            title={t("canvas.videoInput.insertReference")}
                        >
                            <Plus className="size-4" />
                        </button>
                    </Popover>
                ) : (
                    <button
                        type="button"
                        className="grid size-12 shrink-0 place-items-center rounded-xl border bg-transparent transition hover:opacity-70"
                        style={{ borderColor: theme.toolbar.border, color: theme.node.muted }}
                        title={t("canvas.references.select")}
                        onClick={() => onStartSelection?.(nodeId)}
                    >
                        <Plus className="size-4" />
                    </button>
                )}
            </div>
        </div>
    );
}

function ReferenceInputCard({
    item,
    token,
    theme,
    onRemove,
}: {
    item: VideoInputItem;
    token: GlobalToken;
    theme: (typeof canvasThemes)[keyof typeof canvasThemes];
    onRemove?: () => void;
}) {
    const { t } = useTranslation();
    const Icon =
        item.kind === "image"
            ? ImageIcon
            : item.kind === "video"
            ? Video
            : item.kind === "audio"
            ? Music2
            : item.kind === "text"
            ? FileText
            : Users;

    return (
        <Popover placement="topLeft" mouseEnterDelay={0.15} content={<ReferenceInputCardPreview item={item} token={token} theme={theme} />}>
            <div
                className="group relative grid size-12 shrink-0 place-items-center rounded-xl border bg-transparent"
                style={{
                    borderColor: item.disabled ? token.colorErrorBorder : theme.toolbar.border,
                    opacity: item.disabled ? 0.65 : 1,
                }}
            >
                <span className="grid size-full place-items-center overflow-hidden rounded-[inherit]">
                    {(item.kind === "image" || item.kind === "subject") && item.previewUrl ? (
                        <div className="relative size-full">
                            <img src={item.previewUrl} alt="" className="size-full object-cover" />
                            {item.kind === "subject" ? (
                                <span className="absolute bottom-3.5 right-0 rounded-tl bg-black/60 p-0.5 text-white">
                                    <Users className="size-2" />
                                </span>
                            ) : null}
                        </div>
                    ) : item.kind === "video" && item.previewUrl ? (
                        <video src={item.previewUrl} className="size-full object-cover" muted />
                    ) : (
                        <Icon className="size-4 opacity-65" />
                    )}
                </span>
                {item.disabled ? (
                    <span
                        className="absolute right-0.5 top-0.5 rounded px-0.5 text-[8px] font-semibold leading-3"
                        style={{ color: token.colorError, background: token.colorErrorBg }}
                    >
                        {t("canvas.videoInput.issues.unsupportedVideoMedia") || "不支持"}
                    </span>
                ) : null}
                <span
                    className="absolute bottom-0.5 left-0.5 right-0.5 truncate rounded px-0.5 text-center text-[8px] leading-3"
                    style={{ background: theme.toolbar.panel, color: theme.node.text }}
                    title={item.h3Tag ? `${item.h3Tag} ${item.name}` : item.name}
                >
                    {item.h3Tag || (item.kind === "text" ? `文本 ${item.number}` : item.name)}
                </span>
                {onRemove ? (
                    <button
                        type="button"
                        className="absolute right-0 top-0 grid size-5 place-items-center rounded-full border opacity-0 shadow-sm transition-opacity group-hover:opacity-100 focus-visible:opacity-100"
                        style={{ background: theme.toolbar.panel, borderColor: theme.toolbar.border }}
                        aria-label={t("canvas.references.disconnect")}
                        title={t("canvas.references.disconnect")}
                        onMouseDown={(event) => event.stopPropagation()}
                        onClick={(event) => {
                            event.stopPropagation();
                            onRemove();
                        }}
                    >
                        <X className="size-3" />
                    </button>
                ) : null}
            </div>
        </Popover>
    );
}

function ReferenceInputCardPreview({
    item,
    token,
    theme,
}: {
    item: VideoInputItem;
    token: GlobalToken;
    theme: (typeof canvasThemes)[keyof typeof canvasThemes];
}) {
    const { t } = useTranslation();
    return (
        <div className="space-y-2">
            <div className="flex items-center justify-between gap-2 border-b pb-1.5 text-xs font-medium" style={{ borderColor: theme.toolbar.border }}>
                <span className="truncate">{item.h3Tag ? `${item.h3Tag} ${item.name}` : item.name}</span>
                <span className="text-[10px] opacity-60">{item.kind}</span>
            </div>
            {item.disabled ? (
                <div
                    className="rounded p-1 text-xs"
                    style={{ color: token.colorError, background: token.colorErrorBg }}
                >
                    {item.disabledReason || t("canvas.videoInput.issues.unsupportedVideoMedia") || "不支持"}
                </div>
            ) : null}
            {(item.kind === "image" || item.kind === "subject") && item.previewUrl ? (
                <img src={item.previewUrl} alt={item.name} className="max-h-52 w-72 rounded-lg object-contain" />
            ) : item.kind === "video" && item.previewUrl ? (
                <video src={item.previewUrl} className="max-h-52 w-72 rounded-lg" muted controls />
            ) : (
                <div className="max-h-52 w-72 overflow-auto whitespace-pre-wrap text-sm">
                    {item.text || item.name || t("canvas.references.empty")}
                </div>
            )}
        </div>
    );
}

function ReferenceItem({ node, bindingLabels, onRemove }: { node: CanvasNodeData; bindingLabels: string[]; onRemove: () => void }) {
    const { t } = useTranslation();
    const theme = canvasThemes[useThemeStore((state) => state.theme)];
    useSyncExternalStore(subscribeImagePreviews, getImagePreviewRevision);
    const resource = getNodeDefinition(node.type)?.resource?.(node);
    const content = node.metadata?.content || resource?.url;
    const thumbnail = previewUrlFor(node.metadata?.storageKey) || content;
    const Icon =
        resource?.kind === "image" || node.type === CanvasNodeType.Image
            ? ImageIcon
            : resource?.kind === "video" || node.type === CanvasNodeType.Video
            ? Video
            : resource?.kind === "audio" || node.type === CanvasNodeType.Audio
            ? Music2
            : resource?.kind === "text" || node.type === CanvasNodeType.Text
            ? FileText
            : Puzzle;
    return (
        <Popover placement="topLeft" mouseEnterDelay={0.15} content={<ReferencePreview node={node} content={content} bindingLabels={bindingLabels} />}>
            <div className="group relative grid size-12 shrink-0 place-items-center rounded-xl border bg-transparent" style={{ borderColor: theme.toolbar.border }}>
                <span className="grid size-full place-items-center overflow-hidden rounded-[inherit]">
                    {(resource?.kind === "image" || node.type === CanvasNodeType.Image) && thumbnail ? (
                        <img src={thumbnail} alt="" className="size-full object-cover" />
                    ) : (resource?.kind === "video" || node.type === CanvasNodeType.Video) && content ? (
                        <video src={content} className="size-full object-cover" muted />
                    ) : (
                        <Icon className="size-4 opacity-65" />
                    )}
                </span>
                {bindingLabels.length ? (
                    <span className="absolute bottom-0.5 left-0.5 right-0.5 truncate rounded px-0.5 text-center text-[8px] leading-3" style={{ background: theme.toolbar.panel, color: theme.node.text }} title={bindingLabels.join(" · ")}>
                        {t("canvas.videoInput.bindingCount", { count: bindingLabels.length })}
                    </span>
                ) : null}
                <button
                    type="button"
                    className="absolute right-0 top-0 grid size-5 place-items-center rounded-full border opacity-0 shadow-sm transition-opacity group-hover:opacity-100 focus-visible:opacity-100"
                    style={{ background: theme.toolbar.panel, borderColor: theme.toolbar.border }}
                    aria-label={t("canvas.references.disconnect")}
                    title={t("canvas.references.disconnect")}
                    onMouseDown={(event) => event.stopPropagation()}
                    onClick={(event) => {
                        event.stopPropagation();
                        onRemove();
                    }}
                >
                    <X className="size-3" />
                </button>
            </div>
        </Popover>
    );
}

function ReferencePreview({ node, content, bindingLabels }: { node: CanvasNodeData; content?: string; bindingLabels: string[] }) {
    const { t } = useTranslation();
    const theme = canvasThemes[useThemeStore((state) => state.theme)];
    const resource = getNodeDefinition(node.type)?.resource?.(node);
    const preview =
        (resource?.kind === "image" || node.type === CanvasNodeType.Image) && content ? (
            <img src={content} alt={node.title} className="max-h-52 w-72 rounded-lg object-contain" />
        ) : (resource?.kind === "video" || node.type === CanvasNodeType.Video) && content ? (
            <video src={content} className="max-h-52 w-72 rounded-lg" muted controls />
        ) : (resource?.kind === "audio" || node.type === CanvasNodeType.Audio) && content ? (
            <audio src={content} className="w-72" controls />
        ) : (
            <div className="max-h-52 w-72 overflow-auto whitespace-pre-wrap text-sm">
                {resource?.text || node.metadata?.content || node.metadata?.prompt || node.title || t("canvas.references.empty")}
            </div>
        );
    return (
        <div className="space-y-2">
            {preview}
            {bindingLabels.length ? (
                <div className="border-t pt-2 text-xs" style={{ borderColor: theme.toolbar.border }}>
                    <div className="mb-1 font-medium">{t("canvas.videoInput.boundAs")}</div>
                    {bindingLabels.map((label, index) => (
                        <div key={`${label}-${index}`}>{label}</div>
                    ))}
                </div>
            ) : null}
        </div>
    );
}

import { useEffect, useMemo, useRef, useState } from "react";
import type { CSSProperties, KeyboardEvent, MouseEvent, PointerEvent } from "react";
import { Button, Image } from "antd";
import { FileText, Group, Image as ImageIcon, Music2, Video, X } from "lucide-react";
import { useTranslation } from "react-i18next";

import i18n from "@/i18n";
import { canvasThemes } from "@/lib/canvas-theme";
import { useThemeStore } from "@/stores/use-theme-store";
import type { NodeGenerationInput } from "./canvas-node-generation";
import { CanvasNodeReferenceBar } from "./canvas-node-reference-bar";
import { CanvasPromptChipInput, type CanvasPromptChipInputRef } from "./canvas-prompt-chip-input";
import { buildVideoInputList } from "@/lib/canvas/canvas-resource-references";
import { CanvasNodeType, type CanvasConnection, type CanvasGenerationMode, type CanvasNodeData, type CanvasSubject, type CanvasVideoBinding, type VideoInputItem } from "@/types/canvas";

type CanvasConfigComposerProps = {
    nodeId: string;
    nodes: CanvasNodeData[];
    subjects?: CanvasSubject[];
    videoBindings?: CanvasVideoBinding[];
    value: string;
    inputs: NodeGenerationInput[];
    connectedNodes?: CanvasNodeData[];
    connections?: CanvasConnection[];
    generationMode?: CanvasGenerationMode;
    onChange: (value: string) => void;
    onClose: () => void;
    onDisconnectReference?: (fromNodeId: string, toNodeId: string) => void;
    onStartReferenceSelection?: (nodeId: string) => void;
};

type Token =
    | { type: "text"; value: string }
    | { type: "reference"; nodeId: string }
    | { type: "stable"; token: string; label: string; isError?: boolean };

type MentionState = {
    query: string;
};

export const CONFIG_REFERENCE_PATTERN = /@\[node:([^\]]+)\]/g;

export function CanvasConfigComposer({
    nodeId,
    nodes,
    subjects = [],
    videoBindings = [],
    value,
    inputs,
    connectedNodes = [],
    connections = [],
    generationMode,
    onChange,
    onClose,
    onDisconnectReference,
    onStartReferenceSelection,
}: CanvasConfigComposerProps) {
    const { t } = useTranslation();
    const theme = canvasThemes[useThemeStore((state) => state.theme)];
    const editorRef = useRef<HTMLDivElement>(null);
    const chipInputRef = useRef<CanvasPromptChipInputRef>(null);
    const composingRef = useRef(false);
    const lastRangeRef = useRef<Range | null>(null);
    const [mention, setMention] = useState<MentionState | null>(null);
    const [activeIndex, setActiveIndex] = useState(0);
    const [imagePreview, setImagePreview] = useState<string | null>(null);
    const nodeById = useMemo(() => new Map(nodes.map((node) => [node.id, node])), [nodes]);
    const sourceNode = useMemo(
        () => nodes.find((n) => n.id === nodeId) || ({ id: nodeId, type: CanvasNodeType.Config, metadata: { generationMode, videoBindings } } as CanvasNodeData),
        [generationMode, nodeId, nodes, videoBindings]
    );
    const effectiveMode = generationMode || sourceNode.metadata?.generationMode || "image";
    const isVideoMode = effectiveMode === "video";

    const videoInputList = useMemo(() => {
        if (!isVideoMode) return [];
        return buildVideoInputList(sourceNode, nodes, connections, subjects, value, sourceNode.metadata?.model);
    }, [connections, isVideoMode, nodes, sourceNode, subjects, value]);

    const nonVideoInputList: VideoInputItem[] = useMemo(() => {
        if (isVideoMode) return [];
        return inputs.map((inp, idx) => ({
            kind: inp.type === "group" ? "image" : inp.type,
            stableId: `node:${inp.nodeId}`,
            nodeId: inp.nodeId,
            name: inp.title || `Resource ${idx + 1}`,
            number: idx + 1,
            referenced: value.includes(`@[node:${inp.nodeId}]`),
            previewUrl: inp.type === "image" ? inp.image?.url : inp.type === "video" ? inp.video?.url : undefined,
            text: inp.type === "text" ? inp.text : undefined,
        }));
    }, [inputs, isVideoMode, value]);

    const activeInputList = isVideoMode ? videoInputList : nonVideoInputList;

    const stableReferences = useMemo(() => [
        ...subjects.map((subject) => ({ token: `@[subject:${subject.subjectId}]`, label: `Subject: ${subject.name}` })),
        ...videoBindings.map((binding) => ({ token: `@[binding:${binding.bindingId}]`, label: `Binding: ${nodeById.get(binding.nodeId)?.title || binding.nodeId} · ${i18n.t(`canvas.videoInput.usages.${binding.usage}`)}` })),
    ], [nodeById, subjects, videoBindings]);
    const tokens = useMemo(() => parseComposerTokens(value, stableReferences), [stableReferences, value]);
    const referenceById = useMemo(() => new Map(inputs.map((input) => [input.nodeId, input])), [inputs]);
    const candidates = useMemo(() => {
        if (!mention) return [];
        const query = (mention.query || "").trim().toLowerCase();
        if (!query) return inputs;
        return inputs.filter((input) => `${resourceLabel(input, inputs)} ${input.title} ${input.type === "group" ? "" : input.text || ""}`.toLowerCase().includes(query));
    }, [inputs, mention]);

    useEffect(() => {
        if (document.activeElement === editorRef.current) return;
        const editor = editorRef.current;
        if (!editor) return;
        editor.textContent = "";
        tokens.forEach((token) => {
            if (token.type === "text") {
                editor.append(document.createTextNode(token.value));
                return;
            }
            if (token.type === "stable") {
                editor.append(createStableTokenChip(token.token, token.label, theme));
                return;
            }
            const input = referenceById.get(token.nodeId);
            if (input) editor.append(createReferenceChip(input, inputs, theme, setImagePreview));
        });
    }, [inputs, referenceById, theme, tokens]);


    const saveSelection = () => {
        const selection = window.getSelection();
        if (selection && selection.rangeCount > 0 && editorRef.current) {
            const range = selection.getRangeAt(0);
            if (editorRef.current.contains(range.startContainer)) {
                lastRangeRef.current = range.cloneRange();
            }
        }
    };

    const syncFromEditor = () => {
        const editor = editorRef.current;
        if (!editor) return;
        const next = serializeEditor(editor);
        onChange(next);
        syncMention();
    };

    const syncMention = () => {
        const text = textBeforeCaret();
        const match = /@([^\s@]*)$/.exec(text);
        if (!match || !inputs.length) {
            closeMention();
            return;
        }
        setMention({ query: match[1] || "" });
        setActiveIndex(0);
    };

    const closeMention = () => {
        setMention(null);
        setActiveIndex(0);
    };

    const insertReference = (input: NodeGenerationInput) => {
        const editor = editorRef.current;
        if (!editor) return;
        removeActiveMention();
        const chip = createReferenceChip(input, inputs, theme, setImagePreview);
        const space = document.createTextNode(" ");
        const selection = window.getSelection();
        const range = selection?.rangeCount ? selection.getRangeAt(0) : null;
        if (range) {
            range.insertNode(space);
            range.insertNode(chip);
            range.setStartAfter(space);
            range.collapse(true);
            selection?.removeAllRanges();
            selection?.addRange(range);
        } else {
            editor.append(chip, space);
            placeCaretAtEnd(editor);
        }
        closeMention();
        onChange(serializeEditor(editor));
    };

    const insertStableReference = (token: string, customLabel?: string) => {
        const reference = stableReferences.find((item) => item.token === token) || { token, label: customLabel || token };
        const editor = editorRef.current;
        if (!editor) return;
        editor.focus();
        const chip = createStableTokenChip(reference.token, reference.label, theme);
        const space = document.createTextNode(" ");
        let range = lastRangeRef.current;
        const selection = window.getSelection();
        if (selection && selection.rangeCount > 0 && editor.contains(selection.getRangeAt(0).startContainer)) {
            range = selection.getRangeAt(0);
        }
        if (range && editor.contains(range.startContainer)) {
            range.deleteContents();
            range.insertNode(space);
            range.insertNode(chip);
            range.setStartAfter(space);
            range.collapse(true);
            selection?.removeAllRanges();
            selection?.addRange(range);
            lastRangeRef.current = range.cloneRange();
        } else {
            editor.append(chip, space);
            placeCaretAtEnd(editor);
            saveSelection();
        }
        onChange(serializeEditor(editor));
    };

    const stopCanvasInteraction = (event: PointerEvent | MouseEvent) => event.stopPropagation();

    return (
        <div
            data-canvas-no-zoom
            className="rounded-2xl border p-3 shadow-2xl backdrop-blur"
            style={{ background: theme.toolbar.panel, borderColor: theme.toolbar.border, color: theme.node.text }}
            onMouseDown={stopCanvasInteraction}
            onPointerDown={stopCanvasInteraction}
            onWheel={(event) => event.stopPropagation()}
        >
            <div className="mb-2 flex items-center justify-between gap-2">
                <div className="flex min-w-0 items-baseline gap-2">
                    <div className="shrink-0 text-xs font-semibold">{t("canvas.composer.title")}</div>
                    <div className="truncate text-[11px] opacity-55">{t("canvas.composer.description")}</div>
                </div>
                <Button size="small" type="text" className="!h-7 !w-7 !min-w-7 !p-0" icon={<X className="size-3.5" />} onClick={onClose} />
            </div>
            <CanvasNodeReferenceBar
                nodeId={nodeId}
                nodes={nodes}
                connectedNodes={connectedNodes}
                videoBindings={videoBindings}
                subjects={subjects}
                inputList={activeInputList}
                onDisconnect={onDisconnectReference}
                onStartSelection={onStartReferenceSelection}
                onInsertReference={(item) => {
                    if (isVideoMode) {
                        chipInputRef.current?.insertReference(item);
                    } else {
                        const input = referenceById.get(item.nodeId || "");
                        if (input) {
                            insertReference(input);
                        } else {
                            insertStableReference(item.stableId, item.name);
                        }
                    }
                }}
            />
            {isVideoMode ? (
                <div className="relative rounded-xl border p-2" style={{ borderColor: theme.toolbar.border }}>
                    <CanvasPromptChipInput
                        ref={chipInputRef}
                        value={value}
                        references={videoInputList}
                        onChange={onChange}
                        placeholder={t("canvas.composer.placeholder")}
                        className="thin-scrollbar min-h-28 max-h-72 w-full overflow-y-auto overscroll-contain whitespace-pre-wrap break-words px-1 py-1 text-sm leading-7 outline-none"
                        style={{ color: theme.node.text }}
                    />
                </div>
            ) : (
                <div className="relative rounded-xl">
                {!value.trim() ? <div className="pointer-events-none absolute left-3 top-2 text-sm leading-7" style={{ color: theme.node.placeholder }}>{t("canvas.composer.placeholder")}</div> : null}
                <div
                    ref={editorRef}
                    contentEditable
                    suppressContentEditableWarning
                    className="thin-scrollbar min-h-28 max-h-72 w-full overflow-y-auto overscroll-contain whitespace-pre-wrap break-words px-3 py-2 text-sm leading-7 outline-none"
                    style={{ color: theme.node.text }}
                    onClick={saveSelection}
                    onKeyUp={saveSelection}
                    onInput={() => {
                        if (!composingRef.current) syncFromEditor();
                    }}
                    onCompositionStart={() => {
                        composingRef.current = true;
                    }}
                    onCompositionEnd={() => {
                        composingRef.current = false;
                        syncFromEditor();
                    }}
                    onKeyDown={(event: KeyboardEvent<HTMLDivElement>) => {
                        event.stopPropagation();
                        if (mention && candidates.length) {
                            if (event.key === "ArrowDown") {
                                event.preventDefault();
                                setActiveIndex((index) => (index + 1) % candidates.length);
                                return;
                            }
                            if (event.key === "ArrowUp") {
                                event.preventDefault();
                                setActiveIndex((index) => (index - 1 + candidates.length) % candidates.length);
                                return;
                            }
                            if (event.key === "Enter") {
                                event.preventDefault();
                                insertReference(candidates[Math.min(activeIndex, candidates.length - 1)]);
                                return;
                            }
                            if (event.key === "Escape") {
                                event.preventDefault();
                                closeMention();
                                return;
                            }
                        }
                        if ((event.key === "Backspace" || event.key === "Delete") && deleteAdjacentReference(event.key)) {
                            event.preventDefault();
                            requestAnimationFrame(syncFromEditor);
                            return;
                        }
                        requestAnimationFrame(syncMention);
                    }}
                    onBlur={() => window.setTimeout(closeMention, 120)}
                />
                {mention && candidates.length ? <MentionMenu inputs={candidates} allInputs={inputs} activeIndex={Math.min(activeIndex, candidates.length - 1)} theme={theme} onSelect={insertReference} /> : null}
            </div>
            )}
            {imagePreview ? <Image src={imagePreview} alt={t("canvas.composer.imagePreview")} style={{ display: "none" }} preview={{ visible: true, src: imagePreview, onVisibleChange: (visible) => !visible && setImagePreview(null) }} /> : null}
        </div>
    );

}

function MentionMenu({ inputs, allInputs, activeIndex, theme, onSelect }: { inputs: NodeGenerationInput[]; allInputs: NodeGenerationInput[]; activeIndex: number; theme: (typeof canvasThemes)[keyof typeof canvasThemes]; onSelect: (input: NodeGenerationInput) => void }) {
    const selectedRef = useRef(false);
    const activeItemRef = useRef<HTMLButtonElement | null>(null);

    useEffect(() => {
        activeItemRef.current?.scrollIntoView({ block: "nearest" });
    }, [activeIndex, inputs]);

    const selectInput = (input: NodeGenerationInput) => {
        if (selectedRef.current) return;
        selectedRef.current = true;
        onSelect(input);
    };

    return (
        <div className="absolute left-2 top-[calc(100%+6px)] z-[90] max-h-56 w-64 overflow-y-auto rounded-xl border p-1 shadow-2xl" style={{ background: theme.toolbar.panel, borderColor: theme.toolbar.border }}>
            {inputs.map((input, index) => (
                <button
                    key={input.nodeId}
                    ref={index === activeIndex ? activeItemRef : undefined}
                    type="button"
                    className="flex w-full min-w-0 items-center gap-2 rounded-lg px-2 py-1.5 text-left text-xs transition"
                    style={{ background: index === activeIndex ? theme.toolbar.activeBg : "transparent", color: index === activeIndex ? theme.toolbar.activeText : theme.node.text }}
                    onMouseDown={(event) => {
                        event.preventDefault();
                        event.stopPropagation();
                        selectInput(input);
                    }}
                >
                    <ResourcePreview input={input} />
                    <span className="min-w-0 flex-1">
                        <span className="block font-medium">{resourceLabel(input, allInputs)}</span>
                        <span className="block truncate opacity-65">{input.type === "group" ? i18n.t("canvas.node.nodeCount", { count: input.children.length }) : input.text || input.title}</span>
                    </span>
                </button>
            ))}
        </div>
    );
}

function ResourcePreview({ input }: { input: NodeGenerationInput }) {
    if (input.type === "group") return <span className="grid size-9 shrink-0 place-items-center"><Group className="size-4" /></span>;
    if (input.type === "image" && input.image) return <img src={input.image.dataUrl} alt="" className="size-9 rounded-md object-cover" />;
    if (input.type === "video" && input.video) return <video src={input.video.url} className="size-9 rounded-md bg-black object-cover" muted preload="metadata" />;
    const Icon = input.type === "audio" ? Music2 : input.type === "video" ? Video : input.type === "image" ? ImageIcon : FileText;
    return (
        <span className="grid size-9 shrink-0 place-items-center rounded-md bg-black/10">
            <Icon className="size-4" />
        </span>
    );
}

function createReferenceChip(input: NodeGenerationInput, inputs: NodeGenerationInput[], theme: (typeof canvasThemes)[keyof typeof canvasThemes], onImagePreview: (url: string) => void) {
    const wrapper = document.createElement("span");
    wrapper.contentEditable = "false";
    wrapper.dataset.referenceNodeId = input.nodeId;
    wrapper.className = "mx-px inline-flex h-7 max-w-40 items-center justify-center overflow-hidden rounded-md border px-1 text-xs leading-none align-middle";
    Object.assign(wrapper.style, chipStyle(theme));
    if (input.type === "image" && input.image) {
        const image = document.createElement("img");
        image.src = input.image.dataUrl;
        image.alt = input.title;
        image.className = "size-6 rounded object-cover";
        wrapper.className = "mx-px inline-flex size-6 items-center justify-center overflow-hidden rounded align-middle";
        wrapper.appendChild(image);
        wrapper.addEventListener("click", (event) => {
            event.preventDefault();
            event.stopPropagation();
            onImagePreview(input.image?.dataUrl || "");
        });
    } else {
        wrapper.title = input.type === "group" ? input.title : input.text || input.title;
        const text = document.createElement("span");
        text.className = "block truncate";
        text.textContent = input.type === "text" ? input.text || input.title : input.title;
        wrapper.appendChild(text);
    }
    return wrapper;
}

function serializeEditor(editor: HTMLElement) {
    return serializeNodes(editor.childNodes).replace(/\uFEFF/g, "");
}

function serializeNodes(nodes: NodeListOf<ChildNode>) {
    let result = "";
    nodes.forEach((node) => {
        if (node.nodeType === Node.TEXT_NODE) result += node.textContent || "";
        if (!(node instanceof HTMLElement)) return;
        const nodeId = node.dataset.referenceNodeId;
        const token = node.dataset.referenceToken;
        if (token) result += token;
        else if (nodeId) result += `@[node:${nodeId}]`;
        else if (node.tagName === "BR") result += "\n";
        else result += serializeNodes(node.childNodes);
    });
    return result;
}

function removeActiveMention() {
    const selection = window.getSelection();
    if (!selection?.rangeCount) return;
    const range = selection.getRangeAt(0);
    const text = textBeforeCaret();
    const match = /@([^\s@]*)$/.exec(text);
    if (!match) return;
    range.setStart(range.startContainer, Math.max(0, range.startOffset - (match[1] || "").length - 1));
    range.deleteContents();
}

function deleteAdjacentReference(key: string) {
    const selection = window.getSelection();
    if (!selection?.rangeCount || !selection.isCollapsed) return false;
    const range = selection.getRangeAt(0);
    const target = adjacentReferenceNode(range, key);
    if (!target) return false;
    const nextCaretNode = document.createTextNode("");
    target.replaceWith(nextCaretNode);
    range.setStart(nextCaretNode, 0);
    range.collapse(true);
    selection.removeAllRanges();
    selection.addRange(range);
    return true;
}

function adjacentReferenceNode(range: Range, key: string) {
    const container = range.startContainer;
    const offset = range.startOffset;
    const previous = key === "Backspace";
    if (container.nodeType === Node.TEXT_NODE) {
        const text = container.textContent || "";
        if ((previous && offset > 0) || (!previous && offset < text.length)) return null;
        return findReferenceSibling(container, previous);
    }
    const children = Array.from(container.childNodes);
    return findReferenceSibling(children[previous ? offset - 1 : offset] || container, previous, true);
}

function findReferenceSibling(node: Node, previous: boolean, includeSelf = false): HTMLElement | null {
    let current: Node | null = includeSelf ? node : previous ? node.previousSibling : node.nextSibling;
    while (current && current.nodeType === Node.TEXT_NODE && !(current.textContent || "").trim()) current = previous ? current.previousSibling : current.nextSibling;
    return current instanceof HTMLElement && (current.dataset.referenceNodeId || current.dataset.referenceToken) ? current : null;
}

function textBeforeCaret() {
    const selection = window.getSelection();
    if (!selection?.rangeCount) return "";
    const range = selection.getRangeAt(0).cloneRange();
    const editor = closestEditor(range.startContainer);
    if (!editor) return "";
    range.setStart(editor, 0);
    return range.toString();
}

function closestEditor(node: Node) {
    const element = node instanceof Element ? node : node.parentElement;
    return element?.closest("[contenteditable='true']") || null;
}

function placeCaretAtEnd(element: HTMLElement) {
    const range = document.createRange();
    range.selectNodeContents(element);
    range.collapse(false);
    const selection = window.getSelection();
    selection?.removeAllRanges();
    selection?.addRange(range);
}

function parseComposerTokens(value: string, stableReferences: Array<{ token: string; label: string }>): Token[] {
    const tokens: Token[] = [];
    let lastIndex = 0;
    const stableByToken = new Map(stableReferences.map((reference) => [reference.token, reference]));
    const pattern = /@\[(node|subject|binding):([^\]]+)\]/g;
    for (const match of value.matchAll(pattern)) {
        if (match.index === undefined) continue;
        if (match.index > lastIndex) tokens.push({ type: "text", value: value.slice(lastIndex, match.index) });
        if (match[1] === "node") tokens.push({ type: "reference", nodeId: match[2] });
        else {
            const reference = stableByToken.get(match[0]);
            if (reference) tokens.push({ type: "stable", token: reference.token, label: reference.label });
            else tokens.push({ type: "text", value: match[0] });
        }
        lastIndex = match.index + match[0].length;
    }
    if (lastIndex < value.length) tokens.push({ type: "text", value: value.slice(lastIndex) });
    return tokens;
}

function createStableTokenChip(token: string, label: string, theme: (typeof canvasThemes)[keyof typeof canvasThemes]) {
    const wrapper = document.createElement("span");
    wrapper.contentEditable = "false";
    wrapper.dataset.referenceToken = token;
    wrapper.className = "mx-px inline-flex h-7 max-w-48 items-center justify-center overflow-hidden rounded-md border px-1.5 text-xs leading-none align-middle";
    Object.assign(wrapper.style, chipStyle(theme));
    wrapper.title = token;
    const text = document.createElement("span");
    text.className = "block truncate";
    text.textContent = label;
    wrapper.appendChild(text);
    return wrapper;
}

function resourceLabel(input: NodeGenerationInput, inputs: NodeGenerationInput[]) {
    const sameTypeInputs = inputs.filter((item) => item.type === input.type);
    const index = Math.max(0, sameTypeInputs.findIndex((item) => item.nodeId === input.nodeId));
    return i18n.t(`canvas.composer.resources.${input.type}`, { index: index + 1 });
}

function chipStyle(theme: (typeof canvasThemes)[keyof typeof canvasThemes]): CSSProperties {
    return { background: theme.toolbar.panel, borderColor: theme.node.stroke, color: theme.node.text };
}

import type { CSSProperties } from "react";
