        expect(plan.references.find(r => r.nodeId === "D")?.label).toBe(vLabel(0));
        expect(plan.references.find(r => r.nodeId === "G1-1")?.label).toBe(imageReferenceLabel(3));
        expect(plan.references.find(r => r.nodeId === "G1-2")?.label).toBe(imageReferenceLabel(4));
    });

    test("composer mode (empty tokens) includes no resources", () => {
        const configNode = { ...configNodeTemplate, metadata: { composerContent: "just text without tokens" } };
        const plan = resolveReferencePlan(configNode, nodes, connections);
        expect(plan.participatingNodeIds).toEqual([]);
        expect(plan.compiledPrompt).toBe("just text without tokens");
        expect(plan.references.filter(r => r.active)).toHaveLength(0);
        expect(plan.references.find(r => r.nodeId === "A")?.active).toBe(false);
    });

    test("composer mode with tokens dedupes and orders correctly", () => {
        const configNode = { ...configNodeTemplate, metadata: { composerContent: "test @[node:C] and @[node:A]" } };
        const plan = resolveReferencePlan(configNode, nodes, connections);
        expect(plan.participatingNodeIds).toEqual(["C", "A"]);
        expect(plan.references.find(r => r.nodeId === "C")?.label).toBe(imageReferenceLabel(0));
        expect(plan.references.find(r => r.nodeId === "A")?.label).toBe(imageReferenceLabel(1));
        expect(plan.compiledPrompt).toBe(`test ${imageReferenceLabel(0)} and ${imageReferenceLabel(1)}`);
    });

    test("composer mode with tokens respects referenceNodeOrder", () => {
        const configNode = { ...configNodeTemplate, metadata: { composerContent: "test @[node:C] and @[node:A]", referenceNodeOrder: ["A", "B", "C", "D", "G1-1", "G1-2"] } };
        const plan = resolveReferencePlan(configNode, nodes, connections);
        expect(plan.participatingNodeIds).toEqual(["A", "C"]);
        expect(plan.references.find(r => r.nodeId === "A")?.label).toBe(imageReferenceLabel(0));
        expect(plan.references.find(r => r.nodeId === "C")?.label).toBe(imageReferenceLabel(1));
        expect(plan.compiledPrompt).toBe(`test ${imageReferenceLabel(1)} and ${imageReferenceLabel(0)}`);
    });

    test("composer mode expands group token and applies referenceNodeOrder", () => {
        const configNode = { 
            ...configNodeTemplate, 
            metadata: { 
                composerContent: "test @[node:G1] and @[node:A]", 
                referenceNodeOrder: ["G1-2", "A", "G1-1"] 
            } 
        };
        const plan = resolveReferencePlan(configNode, nodes, connections);
        expect(plan.participatingNodeIds).toEqual(["G1-2", "A", "G1-1"]);
        expect(plan.references.find(r => r.nodeId === "G1-2")?.label).toBe(imageReferenceLabel(0));
        expect(plan.references.find(r => r.nodeId === "A")?.label).toBe(imageReferenceLabel(1));
        expect(plan.references.find(r => r.nodeId === "G1-1")?.label).toBe(imageReferenceLabel(2));
        expect(plan.compiledPrompt).toBe(`test ${imageReferenceLabel(0)}、${imageReferenceLabel(2)} and ${imageReferenceLabel(1)}`);
    });

    test("appends new missing resources correctly when referenceNodeOrder is incomplete", () => {
        // Original: A, B, C. Order has B, C. A is new. A should be appended.
        // Wait, "新素材按既有顺序追加，旧项相对顺序保持。"
        // So B, C, A.
        const configNode = { 
            ...configNodeTemplate, 
            metadata: { 
                composerContent: undefined, 
                referenceNodeOrder: ["B", "C"] 
            } 
        };
        const plan = resolveReferencePlan(configNode, nodes, connections);
        expect(plan.participatingNodeIds.slice(0, 3)).toEqual(["B", "C", "A"]);
    });


    test("unparsed tokens are preserved in compiled prompt", () => {
        const configNode = { ...configNodeTemplate, metadata: { composerContent: "test @[node:missing] and @[node:A]" } };
        const plan = resolveReferencePlan(configNode, nodes, connections);
        expect(plan.compiledPrompt).toBe(`test @[node:missing] and ${imageReferenceLabel(0)}`);
    });

    test("unreferenced label responds to i18n locale", () => {
        const configNode = { ...configNodeTemplate, metadata: { composerContent: "test @[node:A]" } };

        if (i18n.changeLanguage) {
            i18n.changeLanguage("en-US");
            let plan = resolveReferencePlan(configNode, nodes, connections);
            let unreferenced = plan.references.find(r => r.nodeId === "B");
            expect(unreferenced?.active).toBe(false);
            expect(unreferenced?.label).toBe("Unreferenced");

            i18n.changeLanguage("zh-CN");
            plan = resolveReferencePlan(configNode, nodes, connections);
            unreferenced = plan.references.find(r => r.nodeId === "B");
            expect(unreferenced?.active).toBe(false);
            expect(unreferenced?.label).toBe("未引用");
        } else {
            let plan = resolveReferencePlan(configNode, nodes, connections);
            let unreferenced = plan.references.find(r => r.nodeId === "B");
            expect(unreferenced?.label).toBe("canvas.configNode.unreferenced");
        }
    });
});

