import { describe, expect, test } from "bun:test";
import { captureCanvasSelection, applyCanvasPaste } from "../src/lib/canvas/canvas-reference-copy";
import type { CanvasNodeData, CanvasConnection } from "../src/types/canvas";

describe("T3: Canvas Reference Copy", () => {
    test("分离捕获与粘贴逻辑：组扩展、保留外部入边与清理临时状态", () => {
        const nodes: CanvasNodeData[] = [
            { id: "group-1", type: "group", position: { x: 0, y: 0 }, metadata: {} },
            { id: "img-1", type: "image", position: { x: 0, y: 0 }, metadata: { groupId: "group-1" } },
            { id: "config-1", type: "config", position: { x: 100, y: 0 }, metadata: { 
                composerContent: "@[node:img-1]", 
                referenceNodeOrder: ["img-1"],
                videoTaskId: "t1",
                status: "done"
            }},
            { id: "ext-out", type: "image", position: { x: 200, y: 0 }, metadata: {} }
        ];
        const connections: CanvasConnection[] = [
            { id: "c-1", fromNodeId: "img-1", toNodeId: "config-1" },
            { id: "c-ext", fromNodeId: "config-1", toNodeId: "ext-out" } // 外部出边
        ];

        // 仅选择 group-1 和 config-1
        const clipboard = captureCanvasSelection(["config-1", "group-1"], nodes, connections);

        // 捕获阶段应自动包含 img-1
        expect(clipboard.nodes).toHaveLength(3); 
        const configSnap = clipboard.nodes.find(n => n.id === "config-1")!;
        expect(configSnap.metadata?.videoTaskId).toBeUndefined(); // 清除临时状态

        expect(clipboard.connections).toHaveLength(1); // 不包含外部出边

        // 粘贴阶段
        const result = applyCanvasPaste(clipboard, nodes, (oldType) => `${oldType}-copy`);

        expect(result.nodes).toHaveLength(3);
        const copiedConfig = result.nodes.find(n => n.id === "config-copy")!;
        const copiedImg = result.nodes.find(n => n.id === "image-copy")!;
        const copiedGroup = result.nodes.find(n => n.id === "group-copy")!;

        expect(copiedImg.metadata?.groupId).toBe("group-copy"); // remap groupId
        expect(copiedConfig.metadata.composerContent).toBe("@[node:image-copy]"); // remap tokens
        expect(copiedConfig.metadata.referenceNodeOrder).toEqual(["image-copy"]); // remap order

        expect(result.connections).toHaveLength(1);
        expect(result.connections[0].fromNodeId).toBe("image-copy");
        expect(result.connections[0].toNodeId).toBe("config-copy");
    });

    test("仅复制配置节点时保留画布中存在的外部入边", () => {
        const nodes: CanvasNodeData[] = [
            { id: "img-ext", type: "image", position: { x: 0, y: 0 }, metadata: {} },
            { id: "config-1", type: "config", position: { x: 100, y: 0 }, metadata: { 
                composerContent: "@[node:img-ext]", 
                referenceNodeOrder: ["img-ext"]
            }}
        ];
        const connections: CanvasConnection[] = [
            { id: "c-1", fromNodeId: "img-ext", toNodeId: "config-1" }
        ];

        // 仅选中 config-1
        const clipboard = captureCanvasSelection(["config-1"], nodes, connections);
        expect(clipboard.nodes).toHaveLength(1);
        expect(clipboard.connections).toHaveLength(1);

        // 目标画布依然包含 img-ext
        const result = applyCanvasPaste(clipboard, nodes, (oldType) => `${oldType}-copy`);

        expect(result.nodes).toHaveLength(1); // config-copy
        expect(result.connections).toHaveLength(1); // 外部入边保留

        const copiedConfig = result.nodes.find(n => n.id === "config-copy")!;
        expect(copiedConfig.metadata.composerContent).toBe("@[node:img-ext]"); // token 不变，因为源仍存在
        expect(result.connections[0].fromNodeId).toBe("img-ext");
        expect(result.connections[0].toNodeId).toBe("config-copy");
    });

    test("多次粘贴必须相互隔离且不修改剪贴板快照 (deep clone metadata/position)", () => {
        const nodes: CanvasNodeData[] = [
            { id: "image", type: "image", position: { x: 0, y: 0 }, metadata: { content: "data:image/png;base64,AA==" } },
            { id: "config", type: "config", position: { x: 0, y: 0 }, metadata: { composerContent: "@[node:image]", referenceNodeOrder: ["image"] } },
        ];
        const connections: CanvasConnection[] = [{ id: "edge", fromNodeId: "image", toNodeId: "config" }];

        const clipboard = captureCanvasSelection(["image", "config"], nodes, connections);
        const original = JSON.stringify(clipboard);

        let i = 0;
        const first = applyCanvasPaste(clipboard, nodes, (t) => `${t}-first-${++i}`);
        expect(JSON.stringify(clipboard)).toBe(original);

        const second = applyCanvasPaste(clipboard, nodes, (t) => `${t}-second-${++i}`);
        const secondImage = second.nodes.find((n) => n.type === "image")!;
        const secondConfig = second.nodes.find((n) => n.type === "config")!;

        expect(secondConfig.metadata?.composerContent).toBe(`@[node:${secondImage.id}]`);
        expect(first.nodes[1].metadata).not.toBe(second.nodes[1].metadata);
    });

    test("copy title responds to i18n locale and empty title remains empty", () => {
        const nodes: CanvasNodeData[] = [
            { id: "config-1", type: "config", title: "My Shot", position: { x: 0, y: 0 }, metadata: {} },
            { id: "config-empty", type: "config", title: "", position: { x: 0, y: 0 }, metadata: {} }
        ];

        const clipboard = captureCanvasSelection(["config-1", "config-empty"], nodes, []);

        // Mock i18n module import for test
        const i18n = require("@/i18n").default;

        let i = 0;
        if (i18n.changeLanguage) {
            i18n.changeLanguage("en-US");
            let result = applyCanvasPaste(clipboard, nodes, (t) => `${t}-en-${++i}`);
            let copiedNamed = result.nodes.find(n => n.id === "config-en-1")!;
            let copiedEmpty = result.nodes.find(n => n.id === "config-en-2")!;
            expect(copiedNamed.title).toBe("My Shot (copy)");
            expect(copiedEmpty.title).toBe("");

            i18n.changeLanguage("zh-CN");
            result = applyCanvasPaste(clipboard, nodes, (t) => `${t}-zh-${++i}`);
            copiedNamed = result.nodes.find(n => n.id === "config-zh-3")!;
            copiedEmpty = result.nodes.find(n => n.id === "config-zh-4")!;
            expect(copiedNamed.title).toBe("My Shot（副本）");
            expect(copiedEmpty.title).toBe("");
        } else {
            // Fallback for global mock in bun test all
            let result = applyCanvasPaste(clipboard, nodes, (t) => `${t}-mock-${++i}`);
            let copiedNamed = result.nodes.find(n => n.id === "config-mock-1")!;
            let copiedEmpty = result.nodes.find(n => n.id === "config-mock-2")!;
            expect(copiedNamed.title).toBe("canvas.configNode.copyTitle");
            expect(copiedEmpty.title).toBe("");
        }
    });
});

