import i18n from "@/i18n";
import { getMediaBlob } from "@/services/file-storage";
import { withLocalProxy } from "@/stores/use-config-store";
import type { CanvasNodeData } from "@/types/canvas";

const downloadError = (key: string, options?: Record<string, unknown>) => i18n.t(`apiErrors.${key}`, options);

/**
 * Message to show when a video save fails. Prefers the categorized cause found by
 * `resolveVideoDownloadBlob` over the generic copy, so the user can tell an expired link from a
 * blocked cross-origin read.
 */
export function videoDownloadErrorMessage(error: unknown, fallback: string) {
    const message = error instanceof Error ? error.message : typeof error === "string" ? error : typeof (error as { message?: unknown })?.message === "string" ? String((error as { message: string }).message) : "";
    return message.trim() || fallback;
}

function isAbortError(error: unknown) {
    return (error as { name?: unknown })?.name === "AbortError";
}

function failureReason(error: unknown) {
    return error instanceof Error && error.message ? error.message : downloadError("videoDownloadFailed");
}

/** Read the MP4 bytes from one candidate URL, classifying a non-OK, empty or rejected response. */
async function readVideoBytes(url: string): Promise<Blob> {
    let response: Response;
    try {
        response = await fetch(url);
    } catch (error) {
        if (isAbortError(error)) throw error;
        throw new Error(downloadError("videoDownloadFetchFailed"));
    }
    if (!response.ok) throw new Error(downloadError("videoDownloadHttpFailed", { status: response.status }));
    const blob = await response.blob();
    if (!blob.size) throw new Error(downloadError("videoDownloadEmpty"));
    return blob;
}

/**
 * Resolve the MP4 bytes to save for a video node.
 * Prefers the already-stored local blob. Otherwise it requests the runtime path first (through the local
 * proxy when it is enabled) and, only when that URL differs from the original signed URL, allows a single
 * alternative GET straight to the original URL. Each candidate URL is requested at most once: no repeats,
 * no polling, no HEAD, and the signed address is passed through unchanged. AbortError propagates
 * immediately so a cancelled save never falls back. When every path fails the categorized reasons are
 * kept, so the caller reports why the save failed instead of a silent or generic success.
 */
export async function resolveVideoDownloadBlob(node: CanvasNodeData): Promise<Blob> {
    const stored = node.metadata?.storageKey ? await getMediaBlob(node.metadata.storageKey).catch(() => null) : null;
    if (stored?.size) return stored;
    const content = node.metadata?.content;
    if (!content) throw new Error(downloadError("videoDownloadNoSource"));

    const candidates = [withLocalProxy(content), content].filter((url, index, list) => Boolean(url) && list.indexOf(url) === index);
    const failures: string[] = [];
    for (const url of candidates) {
        try {
            return await readVideoBytes(url);
        } catch (error) {
            if (isAbortError(error)) throw error;
            failures.push(failureReason(error));
        }
    }
    throw new Error(failures.join("；"));
}

/** UI boundary the download button provides; kept separate so the handler stays testable. */
export type VideoDownloadUi = {
    fallback: string;
    save: (blob: Blob, filename: string) => void;
    notifyFailed: (reason: string) => void;
    confirmOpenOriginal: (url: string, onConfirm: () => void) => void;
    notifyOpened: () => void;
};

/**
 * Save a video node, or hand the user off to the original video when the in-app read fails.
 *
 * The byte-resolution decision stays in `resolveVideoDownloadBlob`; this wrapper only owns the
 * outcome. On success it saves. On AbortError it stays silent, because a cancel is not a failure.
 * On any other failure it shows the categorized reason and offers to open the untouched original
 * address. The original is opened only from the user's own confirmation and is reported as
 * "opened for native saving" -- never as a completed save or as proof an MP4 reached the disk.
 */
export async function downloadVideoNode(node: CanvasNodeData, filename: string, ui: VideoDownloadUi): Promise<void> {
    try {
        ui.save(await resolveVideoDownloadBlob(node), filename);
    } catch (error) {
        if (isAbortError(error)) return;
        ui.notifyFailed(videoDownloadErrorMessage(error, ui.fallback));
        const url = node.metadata?.content;
        if (url) {
            ui.confirmOpenOriginal(url, () => {
                window.open(url, "_blank", "noopener,noreferrer");
                ui.notifyOpened();
            });
        }
    }
}

