export function cleanAutoDLWorkflowId(workflowId: string): string {
    const raw = String(workflowId || "").trim();
    if (!raw) return "";
    const idx = raw.indexOf("::");
    return idx >= 0 ? raw.slice(idx + 2) : raw;
}

export function clampAutoDLDuration(value: string | number | undefined, fallback = 5): number {
    const num = Math.round(Number(value) || fallback);
    return Math.max(1, Math.min(15, num));
}

export function getAutoDLSettingsCapabilities(workflowId: string): AutoDLSettingsCapabilities | null {
    const id = cleanAutoDLWorkflowId(workflowId);
    if (!id || !(id in AUTODL_CAPABILITIES)) {
        return null;
    }
    return AUTODL_CAPABILITIES[id];
}

export function resolveAutoDLResolution(workflowId: string, size?: string, vquality?: string): string {
    const id = cleanAutoDLWorkflowId(workflowId);
    const cap = getAutoDLSettingsCapabilities(id);
    if (!cap) {
        throw new Error(`未知的 AutoDL 工作流: ${workflowId || "未指定"}`);
    }

    const ratio = inferVideoRatio(size || "16:9");
    if (!cap.ratios.includes(ratio)) {
        throw new Error(`AutoDL 工作流 ${id} 不支持所选比例: ${ratio}`);
    }

    if (id === "wan2.2animate-v4-motion_retargeting") {
        return ratio === "9:16" ? "464*832px(竖版)" : "832*464px(横版)";
    }

    const rawQuality = String(vquality ?? "").trim().toLowerCase();
    if (!rawQuality) {
        throw new Error("清晰度不能为空");
    }

    let targetRes = "";

    if (rawQuality === "high" || rawQuality === "medium" || rawQuality === "auto" || rawQuality === "standard") {
        targetRes = "768";
    } else if (rawQuality === "low") {
        targetRes = "480";
    } else if (rawQuality === "720" || rawQuality === "720p") {
        targetRes = "768";
    } else {
        const numMatch = rawQuality.match(/^(\d+)p?$/);
        if (numMatch) {
            targetRes = numMatch[1];
        } else {
            targetRes = rawQuality;
        }
    }

    if (!cap.resolutions.includes(targetRes)) {
        throw new Error(`AutoDL 工作流 ${id} 不支持分辨率: ${vquality || targetRes}`);
    }

    const isSquare = ratio === "1:1";
    const isVertical = ratio === "9:16";

    if (isSquare) {
        return `${targetRes}p(1:1)`;
    }
    if (isVertical) {
        return `${targetRes}p竖`;
    }
    return `${targetRes}p横`;
}

