export async function buildAutoDLRequestBody(
    workflowId: string,
    config: AiConfig,
    prompt: string,
    references: ReferenceImage[],
    options?: VideoMediaOptions,
): Promise<Record<string, unknown>> {
    const id = cleanAutoDLWorkflowId(workflowId);
    const resolution = resolveAutoDLResolution(id, config.size, config.vquality);
    const duration = clampAutoDLDuration(config.videoSeconds, 5);
    const imageUrls = await Promise.all(references.map(resolveAutoDLImageUrl));
    const audioUrls = await Promise.all((options?.audios || []).map((a) => resolveAutoDLAudioUrl(a, options)));
    const videoUrls = await Promise.all((options?.videos || []).map((v) => resolveAutoDLVideoUrl(v, options)));

    const assignment = buildAutoDLSlotAssignment(id, prompt, duration, resolution, imageUrls, audioUrls, videoUrls);

    const body: Record<string, unknown> = {
        prompt: assignment.prompt,
        duration: assignment.duration,
        resolution: assignment.resolution,
        ...assignment.slots,
    };

    if (id === "minimax_h3_image_audio_to_video") {
        return {
            ref_image_0: assignment.slots["ref_image_0"],
            ref_audio_0: assignment.slots["ref_audio_0"],
            audio_duration: assignment.duration,
            resolution: assignment.resolution,
        };
    }

    if (id === "minimax_h3_lightx2v") {
        return {
            prompt: assignment.prompt,
            first_frame: assignment.slots["first_frame"],
            last_frame: assignment.slots["last_frame"],
            duration: assignment.duration,
            resolution: assignment.resolution,
        };
    }

    if (id === "wan2.2animate-v4-motion_retargeting") {
        return {
            ref_image: assignment.slots["ref_image"],
            ref_video: assignment.slots["ref_video"],
            resolution: assignment.resolution,
        };
    }

    return body;
}


