import { asRecord, firstString, normalizeDirectStatus, readDirectError, readPath, readString } from "./shared";
import type { DirectProtocolAdapter } from "./types";

export const autodlDirectProtocol: DirectProtocolAdapter = {
    rawAuthorization: true,
    pollPath: (taskId) => `/api/v1/comfyui/comfyui_workflow/result/${encodeURIComponent(taskId)}`,
    pollURL(baseUrl, taskId) {
        const base = baseUrl.trim().replace(/\/+$/, "");
        return `${base}${this.pollPath(taskId)}`;
    },
    readTaskId: (payload) => readString(readPath(payload, "data.task_id")),
    readCreatedVideoStatus: (payload) => normalizeDirectStatus(readString(readPath(payload, "data.status"))),
    readError: readAutoDLError,
    readImagePoll: () => ({ urls: [], done: false, error: "AutoDL 当前工作流不支持图片生成" }),
    readAudioPoll: (payload) => readAutoDLResult(payload, "audio"),
    readVideoPoll(payload, pollId, model) {
        const result = readAutoDLResult(payload, "video");
        return {
            id: firstString(readPath(payload, "data.task_id"), pollId),
            task_id: firstString(readPath(payload, "data.task_id"), pollId),
            status: result.error ? "failed" : result.done ? "completed" : "processing",
            ...(result.url ? { video_url: result.url, url: result.url } : {}),
            ...(result.error ? { error: { message: result.error } } : {}),
            model,
        };
    },
};

function readAutoDLError(payload: unknown) {
    const code = readPath(payload, "code");
    const error = readDirectError(payload);
    if (error) return error;
    if (String(code).toLowerCase() !== "success") {
        return firstString(readPath(payload, "msg"), readPath(payload, "message"), readPath(payload, "data.message"), `AutoDL 请求失败：${code}`);
    }
    if (normalizeDirectStatus(readString(readPath(payload, "data.status"))) === "failed") {
        return firstString(readPath(payload, "data.message"), readPath(payload, "msg"), "AutoDL 任务失败");
    }
    return "";
}

function readAutoDLResult(payload: unknown, kind: "video" | "audio") {
    const results = readPath(payload, "data.results");
    const output = Array.isArray(results) ? results.map(asRecord).find((item) => item.type === kind && (!item.output_type || item.output_type === "output") && /^https?:\/\//i.test(readString(item.url))) : undefined;
    const url = readString(output?.url);
    const done = normalizeDirectStatus(readString(readPath(payload, "data.status"))) === "completed";
    const error = readAutoDLError(payload) || (done && !url ? `AutoDL 任务已完成但没有返回${kind === "audio" ? "音频" : "视频"}地址` : "");
    return { url, done, error };
}

"use client";

import { useQueries, useQuery } from "@tanstack/react-query";
import { autoDLBaseUrl, isAutoDLConfig } from "@/lib/autodl";
import { fetchAutoDLWorkflow, fetchAutoDLWorkflows } from "@/services/api/autodl";
import type { AiConfig } from "@/stores/use-config-store";

export function useAutoDLWorkflow(config: AiConfig, model = config.model) {
    const baseUrl = autoDLBaseUrl(config, model);
    const enabled = isAutoDLConfig(config, model) && Boolean(model);
    return useQuery({
        queryKey: ["autodl", enabled ? baseUrl : "", model],
        queryFn: () => fetchAutoDLWorkflow(baseUrl, model),
        enabled,
        staleTime: 300_000,
    });
}

type AutoDLChannel = { protocol?: string; baseUrl?: string };

export function useAutoDLWorkflowNames(channels: AutoDLChannel[]) {
    const baseUrls = [...new Set(channels.filter((channel) => channel.protocol === "autodl").map((channel) => (channel.baseUrl || "https://autodl.art").trim().replace(/\/+$/, "")))];
    const queries = useQueries({ queries: baseUrls.map((baseUrl) => ({
        queryKey: ["autodl", baseUrl, "workflows"],
        queryFn: () => fetchAutoDLWorkflows(baseUrl),
        staleTime: 300_000,
    })) });
    return (model: string, channel?: AutoDLChannel | null) => {
        if (channel?.protocol !== "autodl") return model;
        const baseUrl = (channel.baseUrl || "https://autodl.art").trim().replace(/\/+$/, "");
        return queries[baseUrls.indexOf(baseUrl)]?.data?.find((workflow) => workflow.uuid === model)?.name || model;
    };
}

import type { AutoDLWorkflow } from "@/services/api/autodl";
import { channelIdForActiveModel, channelProtocolForConfig, localChannelForActiveModel, type AiConfig } from "@/stores/use-config-store";

export function isAutoDLConfig(config: AiConfig, model = config.model) {
    return channelProtocolForConfig({ ...config, model }) === "autodl";
}

export function autoDLBaseUrl(config: AiConfig, model = config.model) {
    const active = { ...config, model };
    const channel = active.channelMode === "remote"
        ? active.publicChannels.find((item) => item.id === channelIdForActiveModel(active)) || active.publicChannels[0]
        : localChannelForActiveModel(active);
    return (channel?.baseUrl || "https://autodl.art").trim().replace(/\/+$/, "");
}

export function getAutoDLCapabilities(workflow?: AutoDLWorkflow) {
    if (!workflow?.input_rules || workflow.kind === "unsupported") return undefined;
    const rules = workflow.input_rules;
    const images = Object.keys(rules).filter((key) => /^ref_image(?:_\d+)?$/.test(key));
    const audios = Object.keys(rules).filter((key) => /^ref_audio(?:_\d+)?$/.test(key));
    const videos = Object.keys(rules).filter((key) => key === "ref_video");
    return {
        promptRequired: Boolean(rules.prompt?.required),
        imageMax: images.length,
        audioMax: audios.length,
        videoMax: videos.length,
        firstFrame: Boolean(rules.first_frame),
        lastFrame: Boolean(rules.last_frame),
        duration: rules.duration || rules.audio_duration,
    };
}

export function normalizeAutoDLDuration(value: string, workflow?: AutoDLWorkflow) {
    const rule = getAutoDLCapabilities(workflow)?.duration;
    if (!rule) return value;
    const parsed = Number(value.trim() || rule.default);
    if (!Number.isFinite(parsed)) return String(rule.default ?? "");
    const seconds = rule.type === "integer" ? Math.floor(parsed) : parsed;
    return String(Math.min(rule.max ?? Infinity, Math.max(rule.min ?? 0, seconds)));
}

